"use client";

import { Heart, ShoppingBag } from "lucide-react";
import { useTranslations } from "next-intl";
import { Link } from "@/i18n/routing";
import { formatPrice, tJson } from "@/lib/utils";

export type CardProduct = {
  id: string;
  slug: string;
  sku: string;
  name: unknown;
  brand?: string | null;
  retailPrice: number;
  oldPrice: number | null;
  discountPercent: number;
  stockStatus: string;
  stock: number;
  image?: string | null;
  isHit?: boolean;
  isNew?: boolean;
  isSale?: boolean;
};

export function ProductCard({ p, locale }: { p: CardProduct; locale: string }) {
  const t = useTranslations("product");
  const inStock = p.stockStatus === "in_stock" && p.stock > 0;
  const canOrder = true;
  const name = tJson(p.name, locale);

  return (
    <article className="group relative flex min-h-[430px] flex-col overflow-hidden rounded-lg border border-black/10 bg-white shadow-card transition duration-300 hover:-translate-y-1 hover:shadow-[0_22px_60px_rgba(17,18,20,0.12)]">
      <Link href={`/product/${p.slug}`} className="relative aspect-[4/3] overflow-hidden bg-[#eef0ed]">
        {p.image ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={p.image} alt={name} className="h-full w-full object-cover transition duration-700 group-hover:scale-[1.06]" />
        ) : (
          <div className="grid h-full place-items-center text-graphite/30">FORTIS</div>
        )}
        <div className="absolute left-3 top-3 flex flex-wrap gap-1.5">
          {p.discountPercent > 0 && (
            <span className="rounded-full bg-accent px-2.5 py-1 text-[11px] font-semibold text-white">-{p.discountPercent}%</span>
          )}
          {p.isHit && <span className="rounded-full bg-ink px-2.5 py-1 text-[11px] font-semibold text-white">HIT</span>}
          {p.isNew && <span className="rounded-full bg-white px-2.5 py-1 text-[11px] font-semibold">NEW</span>}
        </div>
      </Link>

      <div className="flex flex-1 flex-col p-5">
        <div className="flex items-center justify-between gap-3 text-[11px] uppercase tracking-wide text-graphite/50">
          <span>{p.brand}</span>
          <span className={inStock ? "text-emerald-700" : "text-graphite/50"}>{inStock ? t("inStock") : t("out")}</span>
        </div>
        <Link href={`/product/${p.slug}`} className="mt-2 line-clamp-2 min-h-[2.8em] text-base font-semibold leading-snug">
          {name}
        </Link>
        <div className="mt-1 text-xs text-graphite/50">
          {t("sku")}: {p.sku}
        </div>
        <div className="mt-4 flex items-end gap-2">
          <span className="text-xl font-semibold">{formatPrice(p.retailPrice, locale)}</span>
          {p.oldPrice && <span className="text-sm text-graphite/40 line-through">{formatPrice(p.oldPrice, locale)}</span>}
        </div>

        <div className="mt-auto flex gap-2 pt-5">
          <button
            type="button"
            disabled={!canOrder}
            onClick={async () => {
              await fetch("/api/cart", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ productId: p.id, qty: 1 }),
              });
              window.location.reload();
            }}
            className="focus-ring flex h-11 flex-1 items-center justify-center gap-2 rounded-full bg-ink px-4 text-sm font-medium text-white transition hover:bg-black disabled:opacity-40"
          >
            <ShoppingBag size={16} />
            {t("buy")}
          </button>
          <button
            type="button"
            onClick={() => {
              const raw = localStorage.getItem("fortis_wish") || "[]";
              const ids: string[] = JSON.parse(raw);
              const next = ids.includes(p.slug) ? ids.filter((x) => x !== p.slug) : [...ids, p.slug];
              localStorage.setItem("fortis_wish", JSON.stringify(next));
            }}
            className="focus-ring grid h-11 w-11 shrink-0 place-items-center rounded-full border border-black/10 transition hover:border-ink hover:bg-mist"
            aria-label={t("fav")}
          >
            <Heart size={16} />
          </button>
        </div>
      </div>
    </article>
  );
}
